DROP TABLE IF EXISTS ITEM
CREATE MEMORY TABLE ITEM(ITEM_ID VARCHAR(16) NOT NULL PRIMARY KEY,ITEM_NAME VARCHAR(100) NOT NULL,CATEGORY_CODE VARCHAR(20) NOT NULL,PRICE INTEGER NOT NULL,SALE_PRICE INTEGER,STOCK_QTY INTEGER DEFAULT 0 NOT NULL,STATUS_CODE VARCHAR(10) NOT NULL,IMAGE_URL VARCHAR(500),DESCRIPTION VARCHAR(2000),REG_USER VARCHAR(10),REG_DATE TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL,UPD_DATE TIMESTAMP)
CREATE INDEX IDX_ITEM_CATEGORY ON ITEM(CATEGORY_CODE)
